<?php require __DIR__.'/lib/bootstrap.php';$user=require_auth();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$duration=max(5,(int)($_POST['duration']??60));$price=max(0,(float)str_replace(',','.',$_POST['price']??'0'));$category=trim($_POST['category']??$user['niche']);if($name!==''){$q=db()->prepare('INSERT INTO services(user_id,name,duration,price,category) VALUES(?,?,?,?,?)');$q->execute([$user['id'],$name,$duration,$price,$category]);flash('Serviço cadastrado.');}redirect('servicos.php');}$items=services_for((int)$user['id']);require __DIR__.'/includes/shell-top.php';?>
<h1 class="h1">Serviços e preços</h1><p class="muted">Cadastre o que suas clientes podem agendar.</p><form method="post" class="card" style="margin:20px 0"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><div class="field"><label>Nome do serviço</label><input name="name" required placeholder="Ex.: Esmaltação em gel"></div><div class="grid grid-2"><div class="field"><label>Duração (minutos)</label><input type="number" name="duration" value="60" min="5" required></div><div class="field"><label>Preço (R$)</label><input name="price" type="number" step=".01" min="0" required></div></div><div class="field"><label>Categoria</label><input name="category" value="<?= e($user['niche']) ?>"></div><button class="btn">Adicionar serviço</button></form><div class="card"><?php foreach($items as $s): ?><div class="list-row"><div class="grow"><b><?= e($s['name']) ?></b><div class="muted"><?= (int)$s['duration'] ?> min · <?= e($s['category']) ?></div></div><b><?= brl((float)$s['price']) ?></b></div><?php endforeach; ?></div><p style="margin-top:20px"><a href="perfil.php" class="muted">← Voltar ao perfil</a></p>
